mapper.update:
UPDATE tb_sales_delivery_plan_dt
SET material_id = #{materialId, jdbcType=BIGINT},
    line_no = #{lineNo, jdbcType=INTEGER},
    plan_dt = #{planDt, jdbcType=DATE},
    planned_qty = #{plannedQty, jdbcType=NUMERIC},
    updated_by = #{updatedBy, jdbcType=VARCHAR},
    updated_at = CURRENT_TIMESTAMP
WHERE sales_delivery_plan_detail_id = #{salesDeliveryPlanDetailId, jdbcType=BIGINT}
  AND sales_delivery_plan_id = #{salesDeliveryPlanId, jdbcType=BIGINT}
  AND tenant_id = #{tenantId, jdbcType=BIGINT}
  AND delivered_qty = #{deliveredQty, jdbcType=NUMERIC}

mapper.delete:
DELETE FROM tb_sales_delivery_plan_dt
WHERE sales_delivery_plan_detail_id = #{salesDeliveryPlanDetailId, jdbcType=BIGINT}
  AND sales_delivery_plan_id = #{salesDeliveryPlanId, jdbcType=BIGINT}
  AND tenant_id = #{tenantId, jdbcType=BIGINT}
  AND NOT EXISTS (
      SELECT 1
      FROM tb_sales_delivery_dt dd
      WHERE dd.sales_delivery_plan_detail_id = tb_sales_delivery_plan_dt.sales_delivery_plan_detail_id
        AND dd.tenant_id = tb_sales_delivery_plan_dt.tenant_id
  )

mapper.select:
SELECT COUNT(*)
FROM tb_sales_delivery_dt dd
WHERE dd.sales_delivery_plan_detail_id = #{salesDeliveryPlanDetailId, jdbcType=BIGINT}
  AND dd.tenant_id = #{tenantId, jdbcType=BIGINT}

SELECT
WHERE ph.tenant_id = #{tenantId, jdbcType=BIGINT} AND ph.use_at = 'Y' AND EXISTS ( SELECT 1 FROM tb_sales_delivery_plan_dt pd WHERE pd.sales_delivery_plan_id = ph.sales_delivery_plan_id AND pd.tenant_id = ph.tenant_id
AND pd.plan_dt >= #{planDtFrom, jdbcType=DATE}
AND pd.plan_dt <= #{planDtTo, jdbcType=DATE}
)
AND (ph.plan_no ILIKE '%' || #{keyword} || '%' OR EXISTS ( SELECT 1 FROM tb_sales_delivery_plan_dt pd JOIN tb_sales_order_hd oh ON oh.sales_order_id = pd.sales_order_id AND oh.tenant_id = pd.tenant_id JOIN tb_customer_info c ON c.customer_id = oh.customer_id AND c.tenant_id = oh.tenant_id WHERE pd.sales_delivery_plan_id = ph.sales_delivery_plan_id AND pd.tenant_id = ph.tenant_id AND (oh.order_no ILIKE '%' || #{keyword} || '%' OR c.customer_code ILIKE '%' || #{keyword} || '%' OR c.customer_name ILIKE '%' || #{keyword} || '%') ))
ORDER BY ph.sales_delivery_plan_id DESC
